UPDATE t_stream_checkpoint
SET last_applied_revision = #{revision},
    updated_at = now()
WHERE stream_key = #{streamKey}
  AND last_applied_revision < #{revision}

UPDATE t_link


        SET disabled_reason = disabled_reason & ~CAST(4 AS smallint),
            updated_at = now()
        WHERE user_id = #{userId}
          AND domain_id = #{domainId}
          AND (disabled_reason & CAST(4 AS smallint)) != 0


        SET disabled_reason = disabled_reason | CAST(4 AS smallint),
            updated_at = now()
        WHERE user_id = #{userId}
          AND domain_id = #{domainId}
          AND (disabled_reason & CAST(4 AS smallint)) = 0
